// Extract LM Studio output
const raw = ($json.choices && $json.choices[0] && $json.choices[0].message)
  ? $json.choices[0].message.content
  : '';

// Strip accidental ``` wrappers
let mdx = raw.trim();
if (mdx.startsWith('```mdx')) mdx = mdx.slice(6);
else if (mdx.startsWith('```')) mdx = mdx.slice(3);
if (mdx.endsWith('```')) mdx = mdx.slice(0, -3);
mdx = mdx.trim();

// Sanity: must start with frontmatter
if (!mdx.startsWith('---')) {
  throw new Error('LM Studio output missing frontmatter. Raw: ' + mdx.slice(0, 200));
}

// Grab slug + date from upstream Pick Today Topic node
const upstreamJson = $('Pick Today Topic').item.json;
const slug = upstreamJson.slug;
const date = upstreamJson.today;
const title = upstreamJson.title;

// --- Safety: make colon-bearing frontmatter fields YAML-safe ---
// The model sometimes emits e.g. `title: Saju Fortune Timing: How ...` with an
// unquoted colon, which breaks YAML parsing and used to fail the whole site build.
// Force title/description to be double-quoted with inner quotes/backslashes escaped.
function yamlQuoteScalar(v) {
  let s = String(v).trim();
  if (s.length >= 2 &&
      ((s.charAt(0) === '"' && s.charAt(s.length - 1) === '"') ||
       (s.charAt(0) === "'" && s.charAt(s.length - 1) === "'"))) {
    s = s.slice(1, -1);
  }
  s = s.replace(/\\/g, '\\\\').replace(/"/g, '\\"');
  return '"' + s + '"';
}

const __fmLines = mdx.split(/\r?\n/);
let __fmEnd = -1;
for (let i = 1; i < __fmLines.length; i++) {
  if (__fmLines[i].trim() === '---') { __fmEnd = i; break; }
}
if (__fmEnd > 0) {
  for (let i = 1; i < __fmEnd; i++) {
    const __m = __fmLines[i].match(/^(\s*)(title|description)\s*:\s*(.*)$/);
    if (__m) {
      __fmLines[i] = __m[1] + __m[2] + ': ' + yamlQuoteScalar(__m[3]);
    }
  }
  mdx = __fmLines.join('\n');
}

// Base64 encode
const base64Content = Buffer.from(mdx, 'utf8').toString('base64');

return [{ json: { slug, date, title, mdx, base64Content } }];

// === k-saju Blog Auto-Post — Pre-publish Quality Gate ===
// Pure string/regex checks (no external calls). Source of truth:
// moa-vault 2026-07-08_blog_seo_audit.md §4-A terminology reference.
// Returns { pass, failures:[{code,detail}], warnings:[{code,detail}] }.
// A failure BLOCKS the GitHub push; warnings are informational only.

function validateMdx(mdx) {
  const failures = [];
  const warnings = [];
  const fail = (code, detail) => failures.push({ code, detail });
  const warn = (code, detail) => warnings.push({ code, detail });

  const text = String(mdx || '');

  // --- Split frontmatter / body ---
  let fm = '', body = text;
  const fmMatch = text.match(/^﻿?---\r?\n([\s\S]*?)\r?\n---\r?\n?([\s\S]*)$/);
  if (fmMatch) {
    fm = fmMatch[1];
    body = fmMatch[2];
  }

  // Negation guard for attribution checks (keeps contrasts from tripping FAIL).
  const NEG = /\b(not|non|never|isn'?t|aren'?t|doesn'?t|don'?t|no longer|rather than|instead of|unlike|contrary to|as opposed to|whereas|while western|nothing to do with|myth|misconception|mistaken|wrongly)\b/i;
  const hasNeg = (s) => NEG.test(s);

  // ============ A. TERMINOLOGY ACCURACY (blacklist -> FAIL) ============

  // A1. 오행 misspelling "오항"
  if (/오항/.test(text)) {
    fail('A1_OHAENG_TYPO', 'Found "오항" (misspelling of 오행 / ohaeng).');
  }

  // A2. Five-element romanization mismatch
  // Correct: Wood=Mok, Fire=Hwa, Earth=To, Metal=Geum, Water=Su.
  const ELEM_ROM = { Wood: 'Mok', Fire: 'Hwa', Earth: 'To', Metal: 'Geum', Water: 'Su' };
  // Korean saju romanization tokens (stems/branches/elements) — used to decide
  // whether a captured token is "a Korean term" vs an ordinary English word.
  const KTOKENS = new Set([
    'Mok', 'Hwa', 'To', 'Geum', 'Su',
    'Gap', 'Eul', 'Byeong', 'Jeong', 'Mu', 'Gi', 'Gyeong', 'Sin', 'Im', 'Gye',
    'Ja', 'Chuk', 'In', 'Myo', 'Jin', 'Sa', 'O', 'Mi', 'Yu', 'Sul', 'Hae'
  ]);
  const romPairs = [];
  let m;
  // "Element = Rom" / "Element (Rom" / "Element: Rom" / "Element / Rom".
  // Skip when the element is preceded by a yin/yang polarity word — that is a
  // legitimate STEM parenthetical ("Yang Metal (Gyeong)"), not an element name.
  const reA = /\b(Wood|Fire|Earth|Metal|Water)\b\s*[=:(\/]\s*\(?\s*([A-Z][a-z]{1,5})\b/g;
  while ((m = reA.exec(text)) !== null) {
    const before = text.slice(Math.max(0, m.index - 6), m.index);
    if (/\b(yin|yang)\s*$/i.test(before)) continue;
    romPairs.push([m[1], m[2]]);
  }
  // "Rom (Element)"
  const reB = /\b([A-Z][a-z]{1,5})\s*\(\s*(Wood|Fire|Earth|Metal|Water)\s*\)/g;
  while ((m = reB.exec(text)) !== null) {
    const before = text.slice(Math.max(0, m.index - 6), m.index);
    if (/\b(yin|yang)\s*$/i.test(before)) continue;
    romPairs.push([m[2], m[1]]);
  }
  for (const [el, rom] of romPairs) {
    if (KTOKENS.has(rom) && rom !== ELEM_ROM[el]) {
      fail('A2_ELEMENT_ROMANIZATION', `${el} mapped to "${rom}" (correct: ${ELEM_ROM[el]}).`);
    }
  }

  // A3. Pure-Korean 불/물 used AS the element name (should be 화/수)
  if (/(?:Fire|Water)\s*\(\s*[불물]\s*\)/.test(text) || /[불물]\s*\(\s*(?:Fire|Water)\b/.test(text)) {
    fail('A3_ELEMENT_KOREAN_WORD', 'Element named with 불/물 instead of 화/수.');
  }

  // A4. Fabricated Heavenly Stems.
  // Allowlist of legitimate saju/related hanja (stems, branches, elements, key terms).
  const OK_HANJA = new Set(
    ('甲乙丙丁戊己庚辛壬癸' +        // 10 stems
     '子丑寅卯辰巳午未申酉戌亥' +   // 12 branches
     '木火土金水' +                  // 5 elements
     '四柱八字日干柱大運歲辰十神陰陽宮合節氣天地支五行命理' + // key terms
     '生肖運勢二陽陰星座紫微斗數').split('') // related terms (Chinese zodiac 生肖, etc.)
  );
  const STEM_CTX = /(heavenly stem|천간|cheongan)/i;
  const cjk = text.match(/[㐀-鿿]/g) || [];
  const unknown = [...new Set(cjk.filter((c) => !OK_HANJA.has(c)))];
  if (unknown.length) {
    // FAIL only when an unknown hanja sits close to a "heavenly stem" reference
    // (i.e. the model is inventing stems). Otherwise it is likely an unrelated
    // (but real) term — surface as a warning instead of blocking.
    const nearStem = unknown.filter((c) => {
      let idx = text.indexOf(c);
      while (idx !== -1) {
        const win = text.slice(Math.max(0, idx - 45), idx + 45);
        if (STEM_CTX.test(win)) return true;
        idx = text.indexOf(c, idx + 1);
      }
      return false;
    });
    if (nearStem.length) {
      fail('A4_FABRICATED_STEM', `Non-standard hanja near "heavenly stems": ${nearStem.join(' ')}. Valid stems are 甲乙丙丁戊己庚辛壬癸.`);
    } else {
      warn('A4_UNKNOWN_HANJA', `Unrecognized hanja: ${unknown.join(' ')} (verify these are real saju terms).`);
    }
  }

  // A5. Jyotish hallucination (Saju is NOT Indian astrology)
  if (/jyotish/i.test(text)) {
    fail('A5_JYOTISH', 'Mentions "Jyotish" (Indian astrology) — Saju is Korean, not Jyotish.');
  }

  // Windowed guard: TRUE when a match should be SUPPRESSED because the local
  // context is a contrast / correction (Western astrology, a "myth", solar, or
  // any negation) rather than a positive assertion about Saju.
  const contrastGuard = (win) =>
    hasNeg(win) || /\bwestern\b/i.test(win) || /\bsolar\b/i.test(win) ||
    /\b절기\b/.test(win) || /\bstems? (and|&) branches?\b/i.test(win);
  const around = (idx, len, before, after) =>
    text.slice(Math.max(0, idx - before), idx + len + after);

  // A6. Saju described as lunar-based (it is solar / 절기 based).
  // Match an assertion verb sitting near "lunar", OR a "convert ... to lunar"
  // instruction. Each hit is suppressed by the contrast guard so corrections
  // like "a common myth is that it runs on the lunar calendar" do not trip.
  {
    const pats = [
      /\b(is |are )?(based on|built on|runs on|rooted in|uses|follows|according to|calculated from|relies on)\b[^.;\n]{0,20}\blunar (calendar|system|cycle|months?)\b/gi,
      /\bconvert[a-z]*\b[^.;\n]{0,60}?\b(to|into|onto)\b[^.;\n]{0,25}\blunar\b/gi,
      /\blunar (calendar|system)\b[^.;\n]{0,30}\bto (build|make|read|calculate|get) (your )?(saju|chart|reading)\b/gi
    ];
    for (const re of pats) {
      while ((m = re.exec(text)) !== null) {
        if (contrastGuard(around(m.index, m[0].length, 75, 20))) continue;
        fail('A6_LUNAR_BASED', `Saju tied to the lunar calendar: "${m[0].trim().slice(0, 120)}". Saju is solar/절기-based (year starts at ipchun ~Feb 4).`);
        break; // one hit is enough
      }
    }
  }

  // A7. Saju described via planetary / celestial positions (that is Western astrology).
  // Direction-agnostic: any occurrence of planetary/celestial that sits near a
  // Saju mention is a hallucination UNLESS the window is a Western-contrast /
  // negation (e.g. "Unlike Western astrology, Saju is not based on planetary...").
  {
    const rePlanet = /\b(planet|planetary|celestial (bod(y|ies)|position|movement)s?|position of the (stars|planets)|movement of the planets)\b/gi;
    while ((m = rePlanet.exec(text)) !== null) {
      const win = around(m.index, m[0].length, 90, 90);
      if (!/\b(saju|four pillars|palja)\b/i.test(win)) continue; // must concern Saju
      if (contrastGuard(win)) continue;                          // skip Western contrasts
      fail('A7_PLANETARY', `Saju attributed to planetary/celestial positions: "${win.trim().slice(0, 130)}". Saju reads the calendar of stems & branches.`);
      break;
    }
  }

  // A8. Five-element cycle direction errors (상생 generating / 상극 controlling)
  const GEN = { Wood: 'Fire', Fire: 'Earth', Earth: 'Metal', Metal: 'Water', Water: 'Wood' };     // 상생
  const CTRL = { Wood: 'Earth', Earth: 'Water', Water: 'Fire', Fire: 'Metal', Metal: 'Wood' };    // 상극
  const EL = '(Wood|Fire|Earth|Metal|Water)';
  // Element word incl. common synonyms; normalized back to the canonical name.
  const ELx = '(wood|tree|fire|flame|earth|soil|ground|metal|gold|water)';
  const normEl = (w) => {
    w = w.toLowerCase();
    if (w === 'tree') return 'Wood';
    if (w === 'flame') return 'Fire';
    if (w === 'soil' || w === 'ground') return 'Earth';
    if (w === 'gold') return 'Metal';
    return cap(w);
  };
  // "A controls B" style (A dominates B) — synonym object allowed
  const ctrlActive = new RegExp(`\\b${EL}\\b\\s+(controls?|weakens?|overcomes?|conquers?|restrains?|dominates?|destroys?)\\s+(?:the\\s+)?\\b${ELx}\\b`, 'gi');
  while ((m = ctrlActive.exec(text)) !== null) {
    const a = cap(m[1]), b = normEl(m[3]);
    if (CTRL[a] !== b) fail('A8_CONTROL_CYCLE', `"${m[0]}" is wrong. In the controlling cycle ${a} controls ${CTRL[a]}, not ${b}.`);
  }
  // "A [can be|is|gets] weakened/controlled by B" style (B dominates A).
  // Modal/copula variants + synonym object; small gap lets "wood ... but can be
  // weakened by soil" attach the right subject.
  const ctrlPassive = new RegExp(
    `\\b${EL}\\b[^.;\\n]{0,22}?\\b(?:is|are|can be|could be|may be|might be|gets?|becomes?|will be|being)\\s+(?:being\\s+)?(weakened|controlled|overcome|conquered|restrained|dominated|destroyed|suppressed)\\s+by\\s+(?:the\\s+)?\\b${ELx}\\b`, 'gi');
  while ((m = ctrlPassive.exec(text)) !== null) {
    const a = cap(m[1]), b = normEl(m[3]); // A controlled by B => B controls A
    if (CTRL[b] !== a) fail('A8_CONTROL_CYCLE', `"${m[0].trim()}" is wrong. ${a} is controlled by ${controllerOf(a, CTRL)}, not ${b}.`);
  }
  // "A generates B" style
  const genActive = new RegExp(`\\b${EL}\\b\\s+(generates?|produces?|feeds?|nourishes?|creates?)\\s+(?:the\\s+)?\\b${ELx}\\b`, 'gi');
  while ((m = genActive.exec(text)) !== null) {
    const a = cap(m[1]), b = normEl(m[3]);
    if (GEN[a] !== b) fail('A8_GENERATE_CYCLE', `"${m[0]}" is wrong. In the generating cycle ${a} generates ${GEN[a]}, not ${b}.`);
  }

  // A9a. Ilgan / Day Master wrongly defined as a stem+branch combination
  if (/\b(ilgan|day master)\b[^.]{0,60}\b(combination of[^.]{0,20}(stem|branch|pillar)|stem\s*(\+|and)\s*branch|pillar combination)/i.test(text)) {
    fail('A9_ILGAN_DEF', 'Day Master (ilgan) defined as a stem+branch combination. Ilgan IS the day stem alone.');
  }

  // A9b. Unambiguous yin-yang stem polarity flips
  // Yang stems: Gap, Byeong, Gyeong (unambiguous romanizations). Yin stems: Eul, Jeong, Gye.
  // Window excludes , and . so an adjacent stem's polarity cannot bleed across.
  if (/\b(Gap|Byeong|Gyeong)\b(?:\s*\([^)]*\))?[^.,]{0,12}\byin\b/i.test(text)) {
    fail('A9_YINYANG_STEM', 'A yang stem (Gap/Byeong/Gyeong) labeled yin.');
  }
  if (/\b(Eul|Jeong|Gye)\b(?:\s*\([^)]*\))?[^.,]{0,12}\byang\b/i.test(text)) {
    fail('A9_YINYANG_STEM', 'A yin stem (Eul/Jeong/Gye) labeled yang.');
  }

  // A10. 대운(daeun, ~10yr) confused with daily energy (일진/iljin).
  // The confusion is applying daeun / the "luck pillar" to a DAILY granularity.
  // A correct post keeps them apart (mentions the ten-year scale AND iljin), so
  // each candidate is suppressed when its window shows that separation.
  {
    const sep = /\b(ten[- ]year|10[- ]year|decade|iljin|일진|long[- ]term|annual|세운|seun)\b/i;
    const cands = [
      /\bdaeun\b[^.;\n]{0,45}\b(daily|each day|every day|day[- ]to[- ]day|per day|today'?s)\b/gi,
      /\b(daily|day[- ]to[- ]day|each day|per day|today'?s)\b[^.;\n]{0,25}\bdaeun\b/gi,
      /\bluck pillar\b[^.;\n]{0,45}\b(day|days|daily)\b/gi,
      /\b(each day|a day|days)\b[^.;\n]{0,35}\bluck pillar\b/gi
    ];
    for (const re of cands) {
      let hit = false;
      while ((m = re.exec(text)) !== null) {
        if (sep.test(around(m.index, m[0].length, 70, 70))) continue;
        hit = true; break;
      }
      if (hit) { fail('A10_DAEUN_ILJIN', 'Daeun / the "luck pillar" (a ~10-year cycle) applied to daily energy. A single day is iljin (일진), not daeun.'); break; }
    }
  }

  // M1. Medical / YMYL claims (형 면책 원칙 — Saju is entertainment, not health advice).
  // A concrete health condition tied to a Saju/element context, or a "practice
  // cures/relieves symptoms" claim. Suppressed by an explicit disclaimer window
  // ("not health/medical advice", "consult a professional").
  {
    const MED = /\b(acne|rash(?:es)?|eczema|pimples?|digestive (?:problems?|issues?|trouble)|indigestion|insomnia|anxiety|depression|migraines?|nausea|inflammation|diabetes|blood pressure|cholesterol|disease|illness|ailments?)\b/gi;
    const CTXT = /\b(fire|water|wood|metal|earth|element|energy|saju|imbalance|excess|too much|heat)\b/i;
    const CURE = /\b(cure[sd]?|heal[s]?|treat(?:s|ment)?|remed(?:y|ies)|relieve[sd]?|mitigate[sd]?|reduce[sd]?|alleviate[sd]?|soothe[sd]?)\b/i;
    const DISCLAIM = /\b(not (?:medical|health|professional) advice|entertainment|self[- ]reflection|consult (?:a|your)? ?(?:qualified )?(?:professional|doctor|physician))\b/i;
    while ((m = MED.exec(text)) !== null) {
      const win = around(m.index, m[0].length, 90, 90);
      if (DISCLAIM.test(win)) continue;               // it's the disclaimer line itself
      if (CTXT.test(win) || CURE.test(win)) {
        fail('M1_MEDICAL_YMYL', `Health/medical claim near "${m[0]}": "${win.trim().slice(0, 120)}". Saju content must stay entertainment/self-reflection, not health advice.`);
        break;
      }
    }
  }

  // A11. Birth-hour -> branch(animal/element) mismatch
  // 2-hour blocks by start hour (24h): animal + element.
  const HOURS = [
    [23, 'Rat', 'Water'], [1, 'Ox', 'Earth'], [3, 'Tiger', 'Wood'], [5, 'Rabbit', 'Wood'],
    [7, 'Dragon', 'Earth'], [9, 'Snake', 'Fire'], [11, 'Horse', 'Fire'], [13, 'Goat', 'Earth'],
    [15, 'Monkey', 'Metal'], [17, 'Rooster', 'Metal'], [19, 'Dog', 'Earth'], [21, 'Pig', 'Water']
  ];
  const startToRow = {};
  HOURS.forEach((r) => { startToRow[r[0]] = r; });
  const ANIMALS = 'Rat|Ox|Tiger|Rabbit|Dragon|Snake|Horse|Goat|Sheep|Ram|Monkey|Rooster|Cock|Chicken|Dog|Pig|Boar';
  const to24 = (h, ap) => {
    h = parseInt(h, 10);
    if (!ap) return h;
    ap = ap.toLowerCase();
    if (ap === 'am') return h === 12 ? 0 : h;
    return h === 12 ? 12 : h + 12;
  };
  const normAnimal = (a) => {
    a = a.toLowerCase();
    if (a === 'sheep' || a === 'ram') return 'Goat';
    if (a === 'cock' || a === 'chicken') return 'Rooster';
    if (a === 'boar') return 'Pig';
    return a.charAt(0).toUpperCase() + a.slice(1);
  };
  // "7-9 AM ... Dragon" / "7 AM - 9 AM ... Pig(=Earth)"
  const hourRe = new RegExp(
    `\\b(\\d{1,2})\\s*(am|pm)?\\s*[-–—]{1,2}\\s*(\\d{1,2})\\s*(am|pm)\\b[\\s\\S]{0,40}?\\b(${ANIMALS})\\b`, 'gi'
  );
  while ((m = hourRe.exec(text)) !== null) {
    const start = to24(m[1], m[2] || m[4]); // borrow trailing meridiem if start lacks one
    const claimed = normAnimal(m[5]);
    const row = startToRow[start];
    if (row && claimed !== row[1]) {
      fail('A11_HOUR_BRANCH', `${m[1]}${(m[2] || '')}–${m[3]}${m[4]} is the ${row[1]} hour (${row[2]}), not ${claimed}.`);
    }
  }

  // ============ C. SEO / STRUCTURE ============

  // C1. Frontmatter present
  if (!fmMatch) {
    fail('C1_NO_FRONTMATTER', 'Missing YAML frontmatter (--- ... --- block).');
  } else {
    const fmField = (name) => {
      const r = new RegExp(`^\\s*${name}\\s*:\\s*(.+?)\\s*$`, 'im');
      const mm = fm.match(r);
      return mm ? mm[1].trim() : null;
    };
    const title = fmField('title');
    const desc = fmField('description');
    if (!title) fail('C2_NO_TITLE', 'Frontmatter missing a title.');
    if (!desc) {
      fail('C3_NO_DESCRIPTION', 'Frontmatter missing a meta description.');
    } else {
      const dLen = desc.replace(/^["']|["']$/g, '').length;
      if (dLen < 100 || dLen > 170) {
        warn('C3_DESC_LENGTH', `Meta description is ${dLen} chars (target ~120-160).`);
      }
    }
    for (const f of ['date', 'slug', 'category', 'keywords', 'tags', 'author']) {
      if (!fmField(f)) warn('C_FM_FIELD', `Frontmatter missing "${f}".`);
    }
  }

  // C4. At least one H2 (SEO nit, not brand-damaging -> WARN)
  if (!/^##\s+\S/m.test(body)) {
    warn('C4_NO_H2', 'Body has no H2 (## ) heading (starts at H3?).');
  }
  // C4b. Body must not start with H1 (page renders the title as H1 already)
  if (/^#\s+\S/m.test(body)) {
    warn('C4_H1_IN_BODY', 'Body contains an H1 (# ) — the page already renders the title as H1.');
  }

  // C5. Word count
  const words = (body.replace(/[`*_#>\[\]()!-]/g, ' ').match(/\b[\w']+\b/g) || []).length;
  if (words < 250) {
    fail('C5_TOO_SHORT', `Body is only ${words} words (looks truncated; min 250 to publish).`);
  } else if (words < 700) {
    warn('C5_THIN', `Body is ${words} words (audit target ~700+).`);
  }

  // C6. Hero image present with a non-empty alt (SEO nit -> WARN)
  const img = body.match(/!\[([^\]]*)\]\(([^)]+)\)/);
  if (!img) {
    warn('C6_NO_IMAGE', 'No image found in body.');
  } else if (!img[1].trim()) {
    warn('C6_EMPTY_ALT', 'Image has an empty alt text.');
  }

  return { pass: failures.length === 0, failures, warnings };
}

function cap(s) { return s.charAt(0).toUpperCase() + s.slice(1).toLowerCase(); }
function controllerOf(target, CTRL) {
  for (const k in CTRL) if (CTRL[k] === target) return k;
  return '?';
}

// --- n8n glue ---
const mdx = $json.mdx || '';
const _validation = validateMdx(mdx);
return [{ json: { ...$json, _validation } }];
